public class Ex11PaginationRewrite {

    static String upper(String s) {
        return s.toUpperCase();
    }

    // PageHelper 实际追加 "LIMIT ?,?" 并把 offset/size 作为参数绑定；
    // 此处用字面量便于直接观察改写结果。
    static String pageSql(String sql, int page, int size) {
        String s = sql.trim();
        if (upper(s).contains("UNION")) {
            s = "SELECT * FROM (" + s + ") tmp";
        }
        int offset = (page - 1) * size;
        return s + " LIMIT " + offset + "," + size;
    }

    static String countSql(String sql) {
        String s = sql.trim();
        String u = upper(s);
        if (u.contains("GROUP BY") || u.contains("DISTINCT") || u.contains("UNION")) {
            return "SELECT count(0) FROM (" + s + ") tmp";
        }
        int order = u.indexOf(" ORDER BY");
        if (order >= 0) {
            s = s.substring(0, order).trim();
        }
        int from = upper(s).indexOf(" FROM ");
        return "SELECT count(0)" + s.substring(from);
    }

    // 结构性判据：count 查询是否只返回一行
    static boolean singleRowCount(String countSql) {
        String u = upper(countSql);
        return !u.contains("GROUP BY") && !u.contains(" UNION ");
    }

    public static void main(String[] args) {
        String plain = "SELECT * FROM t_user WHERE status = 1 ORDER BY id DESC";
        System.out.println("orig            : " + plain);
        System.out.println("page 2/size 10  : " + pageSql(plain, 2, 10));
        System.out.println("count (plain)   : " + countSql(plain));

        String grouped = "SELECT dept_id, count(0) c FROM t_user GROUP BY dept_id";
        System.out.println("groupby count   : " + countSql(grouped));

        String union = "SELECT id FROM a UNION SELECT id FROM b";
        System.out.println("union page      : " + pageSql(union, 1, 5));
        System.out.println("union count     : " + countSql(union));

        System.out.println("count plain 1row: " + singleRowCount(countSql(plain)));
        String naive = "SELECT count(0) FROM t_user GROUP BY dept_id";
        System.out.println("naive count sql : " + naive);
        System.out.println("naive count 1row: " + singleRowCount(naive));
        System.out.println("naive wrong     : " + (!singleRowCount(naive)));
    }
}
